import PropTypes from 'prop-types'
import { RadioWithChildrenStyle, RadioChildrenStyle } from './index.style'
import { useCallback } from 'react'
import { SELECTION_ARROW } from '../../../../images'
import CustomText from '../../../CustomText/index'
import { Row } from '../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../configs/colorPallete'

function RadioWithChildren ({
  name, data, children, id, defaultSelected,
  disabled, className, onChange, label, error, selected,
  onClick = () => {}, disabledKey, isBtmBorder
}) {
  const handleOnChange = useCallback((item) => {
    // pass the selected item to parent
    if (onChange) {
      onChange({
        name,
        ...item
      })
    }
  }, [name, onChange])

  const renderRadioLabel = useCallback(() => {
    return (
      <Row align='center' justify='space-between' className='radio-label-text'>
        <div>
          <div className='radio-label-title'>
            {label}
          </div>
          {
            data.subText && (
              <CustomText
                size='0.8em'
                color={AgentColorPallette.fontGrey}
              >
                {data.subText}
              </CustomText>
            )
          }
        </div>
        {
          data.isArrow && (
            <img src={SELECTION_ARROW} alt='' />
          )
        }
      </Row>
    )
  }, [data, label])

  return (
    <RadioWithChildrenStyle
      className={className}
      key={data.id}
      onClick={() => {
        onChange && onChange(data, disabled)
        onClick && onClick(data, disabled)
      }}
      isBtmBorder={isBtmBorder}
      borderColor={error && AgentColorPallette.errorDark}
    >
      <RadioChildrenStyle
        disabled={disabled || (disabledKey === data.id)}
        borderColor={error && AgentColorPallette.errorDark}
        isSubText={!!data.subText}
      >
        <label
          className='radio-container'
        >
          {renderRadioLabel(data)}
          <input
            type='radio'
            checked={data.id === selected}
            name={name}
            value={data.value}
            onChange={(e) => {
              if (disabled || (disabledKey === data.id)) return false
              handleOnChange(data)
            }}
            disabled={disabled || (disabledKey === data.id)}
          />
          <span className='checkmark' />
        </label>
      </RadioChildrenStyle>
      <div className='radio-children'>
        {data.id === selected && children}
      </div>
    </RadioWithChildrenStyle>
  )
}

RadioWithChildren.propsType = {
  selected: PropTypes.string,
  name: PropTypes.string,
  data: PropTypes.object,
  disabled: PropTypes.bool,
  isBtmBorder: PropTypes.bool,
  onChange: PropTypes.func
}

export default RadioWithChildren
