import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useAgentAddressStateValue } from '../../context'
import {
  updateAgentAddress
} from '../actions'

export const useAgentAddressServiceCall = (actionsCall = () => {}) => {
  const [cargoState, dispatch] = useAgentAddressStateValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [cargoState, request]
}

export const useUpdateAgentAddress = () => useAgentAddressServiceCall(updateAgentAddress)
