import _ from 'lodash'
import { useState, useRef, useCallback, useEffect } from 'react'
import { useGetPopupApiOptions } from '../../../../../containers/Private/DynamicPurchaseFlow/services'

function usePopupApiOptions(apiConfig) {
  const [options, setOptions] = useState([])
  const isFetched = useRef(false)

  const {
    state: { getPopupApiOptionsData },
    request: getPopupApiOptionsReq,
    loaders: { GET_POPUP_API_OPTIONS_LOADER },
  } = useGetPopupApiOptions()

  const fetchOptions = useCallback(() => {
    if (!apiConfig?.url || isFetched.current) return
    isFetched.current = true
    getPopupApiOptionsReq({ url: apiConfig.url })
  }, [apiConfig, getPopupApiOptionsReq])

  useEffect(() => {
    // Fetch options on mount
    fetchOptions()
  }, [fetchOptions])

  useEffect(() => {
    if (!getPopupApiOptionsData || !apiConfig) return
    const {
      response_list_key = '',
      response_display_key = '',
      response_value_key = '',
      response_pinned_flag_key,
      response_description_key = '',
    } = apiConfig
    const rawList = _.get(getPopupApiOptionsData, response_list_key, [])
    setOptions(
      rawList.map((item) => ({
        label: item[response_display_key],
        value: item[response_value_key],
        is_pinned: item[response_pinned_flag_key] ?? false,
        ...(response_description_key != null &&
        response_description_key !== '' &&
        item[response_description_key] != null
          ? { description: item[response_description_key] }
          : {}),
      }))
    )
  }, [getPopupApiOptionsData, apiConfig])

  return { options, isLoadingOptions: GET_POPUP_API_OPTIONS_LOADER, fetchOptions }
}

export default usePopupApiOptions
