import { forwardRef } from 'react'
import DynamicForm from '../../../../../../../components/DynamicForm'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { getCustomerDocForm } from '../../constants'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { useState } from 'react'
import { useEffect } from 'react'

function CustomerDocument({ customerData = {}, onChange }, parentRef) {
  const [rerender, setRerender] = useState(0)

  useEffect(() => {
    // rerender for ocr set auto fill ktp
    if (typeof customerData?.ktp_no === 'string') {
      setRerender((prev) => prev + 1)
    }
  }, [customerData?.ktp_no])

  return (
    <>
      <CustomText
        color={AgentColorPallette.black}
        size="1em"
        top="1.2em"
        bottom="0.5em"
        weight={700}
      >
        {LANG_STRINGS.customerData}
      </CustomText>
      <DynamicForm
        key={rerender.toString()}
        form={getCustomerDocForm(customerData)}
        ref={parentRef}
        onChange={onChange}
        formName="customerDocForm"
        isValidateOnChange
        isDocSlider
      />
    </>
  )
}

export default forwardRef(CustomerDocument)
