import { useRef, useEffect, useCallback, useState, useMemo } from 'react'
import moment from 'moment'
import {
  useLoaderContextValue,
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { Button, Container } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang/index'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import { useGetDraftQuoteDetails, useUpdateDraftQuote } from '../../../state/hooks/usePolicyState'
import { HARD_COPY_OPTION, SEND_TO_CUSTOMER } from '../../../../../../constants/hardCopy'
import QuoteSaveConfirmModal from '../../../../../../components/QuoteSaveConfirmModal'
import CustomerSurveyForm from '../components/CustomerSurveyForm'
import { useSaveCustomerData } from '../../../../../../state/globalState/hooks/useGlobalContext'
import { useBackButton } from '../../../../../../state/commonState/hooks/useBackButton'
import { checkValidateStartDate } from '../../../../../../helpers/utility'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { USER } from '../../../../../../images'
import { POLICY_STEPS } from '../../../constants'
import FixedTab from '../components/FixedTab'
import CustomerDocument from '../components/CustomerDocument'
import CustomerNameSection from '../components/CustomerNameSection'
import CustomerAddress from '../components/CustomerAddress'
import HardCopySection from '../components/HardCopySectionV2'
import { MVPolicyCustomerStyle, PageContainer, ButtonContainer } from './index.style'
import { useOcrKtpService } from '../hooks/useOcrKtpService'
import { MV_RENEWAL_STATUS } from '../../../../../../constants/pkgCode'

function MVPolicyCustomerDataContainer({ match, history }) {
  const [
    {
      DRAFT_QUOTATIONS_DETAILS_LOADER,
      UPDATE_DRAFT_QUOTATION_LOADER,
      POST_DRAFT_POLICY_OCR_LOADER,
    },
  ] = useLoaderContextValue()
  const [{ updateDraftQuotationStatus, draftQuotationsDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [, setShowReview] = useState()
  const [enableSave, setEnableSave] = useState(false)
  const [showQuoteConfirm, setShowQuoteConfirm] = useState(false)
  const savedCustomerDataToGlobalStore = useSaveCustomerData()
  const [lastActionType, setLastActionType] = useState(null)
  // this details comes from the data
  const policyDetails = useMemo(() => {
    return draftQuotationsDetailsData.policy_details
      ? {
          ...draftQuotationsDetailsData.policy_details,
          customer_address:
            draftQuotationsDetailsData.policy_details?.customer_address ||
            draftQuotationsDetailsData.policy_details?.customer_data?.customer_address,
          provider_survey: draftQuotationsDetailsData.provider_survey,
        }
      : null
  }, [draftQuotationsDetailsData])

  const hardCopyData = useMemo(() => {
    if (!policyDetails) return {}
    return {
      hard_copy_required: policyDetails?.hard_copy_required,
      hard_copy_sent_to: policyDetails?.hard_copy_sent_to,
      hard_copy_sent_to_name:
        (HARD_COPY_OPTION.find((opt) => opt.id === policyDetails?.hard_copy_sent_to) || {})?.name ||
        '',
      customer_address: policyDetails?.customer_address,
      customer_name: policyDetails?.customer_data?.name,
      mobile_no: policyDetails?.customer_data?.mobile_no,
      hard_copy_address: policyDetails?.hard_copy_address,
      hard_copy_recipient:
        policyDetails?.hard_copy_recipient ||
        (policyDetails.hard_copy_sent_to === SEND_TO_CUSTOMER
          ? policyDetails?.customer_data?.name
          : ''),
      hard_copy_recipient_mobile:
        policyDetails?.hard_copy_recipient_mobile ||
        (policyDetails.hard_copy_sent_to === SEND_TO_CUSTOMER
          ? policyDetails?.customer_data?.mobile_no
          : ''),
    }
  }, [policyDetails])

  const customerDocRef = useRef()
  const customerNameRef = useRef()
  const customerAddressRef = useRef()
  const updateDraftTimer = useRef()
  const savedDraftData = useRef({})
  const hardCopyRef = useRef()
  const surveyFormRef = useRef()

  const that = useRef({
    draftQuoteId: match?.params?.draftQuoteId,
    formData: { customer_data: {}, customer_address: {} },
  })
  const addBackEventListener = useBackButton()

  const handleSaveDraftKtp = (data) => {
    const city = policyDetails?.customer_address || {}

    if (typeof data?.city?.region === 'number') {
      city.city_code = data.city.city_code
      city.city_name = data.city.city_name
      city.region = data.city.region
    } else {
      delete city.city_code
      delete city.city_name
      delete city.region
    }

    const customerAddress = {
      ...city,
      address: data.full_address,
      province_code: data.province.province_code,
      province_name: data.province.province_name,
    }

    handleSaveDraft(
      {
        ktp_use_ocr: true,
        ktp_no: data?.nik,
        customer_data: {
          ...policyDetails?.customer_data,
          name: data?.name,
        },
        customer_address: customerAddress,
      },
      50
    )
  }

  const { handleKtpOcr } = useOcrKtpService({
    draftId: that.current.draftQuoteId,
    handleErrorOcr: () =>
      handleSaveDraft(
        {
          ktp_use_ocr: false,
          ktp_no: '',
          customer_data: { name: '' },
          customer_address: { address: '' },
        },
        50
      ),
    handleSaveDraftKtp,
  })

  useEffect(() => {
    getDraftQuoteDetailsReq({
      draftQuoteId: that.current.draftQuoteId,
    })
  }, [getDraftQuoteDetailsReq])

  // Chrome autofill prevention
  useEffect(() => {
    const preventChromeAutofill = () => {
      // Wait for form to be rendered
      setTimeout(() => {
        const inputs = document.querySelectorAll('#ssg-container input, #ssg-container textarea')

        inputs.forEach((input) => {
          // Skip hidden, submit, and button inputs
          if (input.type === 'hidden' || input.type === 'submit' || input.type === 'button') {
            return
          }

          // Add Chrome-specific autofill prevention attributes
          input.setAttribute('autocomplete', 'chrome-off')
          input.setAttribute('data-lpignore', 'true')
          input.setAttribute('data-form-type', 'other')

          // Add random name suffix to confuse Chrome autofill
          if (input.name && !input.getAttribute('data-original-name')) {
            input.setAttribute('data-original-name', input.name)
            const randomSuffix = Math.random().toString(36).substring(2, 15)
            input.name = `${input.name}_${randomSuffix}`
          }

          // Add event listeners to prevent autofill
          const handleFocus = () => {
            // Clear any autofilled value on focus
            if (input.value && !input.getAttribute('data-user-entered')) {
              const originalValue = input.getAttribute('data-original-value')
              if (!originalValue) {
                // This is likely autofilled, clear it
                setTimeout(() => {
                  if (input.value && !input.getAttribute('data-user-entered')) {
                    input.value = ''
                  }
                }, 10)
              }
            }
          }

          const handleInput = () => {
            // Mark as user-entered when user starts typing
            input.setAttribute('data-user-entered', 'true')
          }

          const handleBlur = () => {
            // Store the value if user entered something
            if (input.value) {
              input.setAttribute('data-original-value', input.value)
            }
          }

          input.addEventListener('focus', handleFocus)
          input.addEventListener('input', handleInput)
          input.addEventListener('blur', handleBlur)

          // Store original value if it exists
          if (input.value) {
            input.setAttribute('data-original-value', input.value)
          }
        })
      }, 300)
    }

    if (policyDetails) {
      preventChromeAutofill()
    }
  }, [policyDetails])

  // Restore original field names before form submission
  const restoreFieldNames = useCallback(() => {
    const inputs = document.querySelectorAll('#ssg-container input, #ssg-container textarea')
    inputs.forEach((input) => {
      const originalName = input.getAttribute('data-original-name')
      if (originalName) {
        input.name = originalName
      }
    })
  }, [])

  const handleCloseReview = useCallback(() => {
    setShowReview(false)
  }, [])

  useEffect(() => {
    if (updateDraftQuotationStatus === 'success' && lastActionType === 'saveDraft') {
      clearTimeout(updateDraftTimer.current)
      history.push({
        pathname: `/motor_vehicle/confirmation/${that.current.draftQuoteId}`,
      })
    }
  }, [updateDraftQuotationStatus, lastActionType, history])

  useEffect(() => {
    if (updateDraftQuotationStatus === 'success') {
      // show loader only when click on buy
      if (that.current.isReviewCall) {
        that.current.isReviewCall = false
        setShowReview(true)
      } else if (that.current.isSaveClick) {
        that.current.isSaveClick = false
        setEnableSave(false)
        setShowQuoteConfirm(true)
      }
      resetError(['updateDraftQuotationStatus'])
    }
    if (draftQuotationsDetailsStatus === 'success' && !that.current.removeEvent) {
      const isReviewPage = draftQuotationsDetailsData?.sub_section === 'mv_quote_summary'
      that.current.removeEvent = addBackEventListener(
        {
          section: 'customer_data',
          draftId: draftQuotationsDetailsData.id,
        },
        isReviewPage && handleCloseReview
      )
      if (!checkValidateStartDate(draftQuotationsDetailsData?.policy_details?.start_date)) {
        savedDraftData.current.start_date = moment().format('YYYY-MM-DD')
        if (draftQuotationsDetailsData?.policy_details?.premium_changed) {
          ShowSnackbar.success({
            visible: true,
            text: LANG_STRINGS.premiumCoverageHaveBeenChanged,
          })
        } else {
          ShowSnackbar.success({
            visible: true,
            text: LANG_STRINGS.policyStartDateHasBeenChangedToCurrent,
          })
        }
        updateDraftQuoteReq({
          body: {
            section: 'customer_data',
            sub_section: 'customer_document',
            data: {
              ...draftQuotationsDetailsData?.policy_details,
              start_date: savedDraftData.current.start_date,
            },
          },
          draftQuoteId: that.current.draftQuoteId,
        })
      } else if (draftQuotationsDetailsData?.policy_details?.premium_changed) {
        ShowSnackbar.success({
          visible: true,
          text: LANG_STRINGS.premiumHaveBeenChanged,
        })
      }
      savedCustomerDataToGlobalStore({
        ...draftQuotationsDetailsData?.customer_detail,
        customer_address: {
          ...draftQuotationsDetailsData?.policy_details?.customer_address,
        },
      })
      if (draftQuotationsDetailsData?.status === 'completed') {
        return history.replace('/dashboard')
      }
      that.current.formData = {
        ktp_no: draftQuotationsDetailsData.policy_details?.ktp_no,
        ktp_url: draftQuotationsDetailsData.policy_details?.ktp_url,
        customer_address: draftQuotationsDetailsData.policy_details?.customer_address,
        customer_data: draftQuotationsDetailsData.policy_details?.customer_data,
      }
      if (isReviewPage) {
        window.history.pushState(null, null, window.location.pathname)
        setShowReview(true)
      }
      resetError(['draftQuotationsDetailsStatus'])
    }
  }, [
    updateDraftQuotationStatus,
    draftQuotationsDetailsStatus,
    draftQuotationsDetailsData,
    resetError,
    history,
    savedCustomerDataToGlobalStore,
    updateDraftQuoteReq,
    addBackEventListener,
    handleCloseReview,
  ])

  const handleSaveDraft = useCallback(
    (extraData = {}, timer) => {
      savedDraftData.current = {
        ...draftQuotationsDetailsData.policy_details,
        ...savedDraftData.current,
        ...extraData,
      }
      if (updateDraftTimer.current) {
        clearTimeout(updateDraftTimer.current)
        updateDraftTimer.current = ''
      }
      if (that.current.isReviewCall) {
        savedDraftData.current = {
          ...policyDetails?.package_data,
          provider_branch: policyDetails?.package_data?.provider?.headquarter_branch,
          ...savedDraftData.current,
          ...savedDraftData.current.addons_data,
        }
        delete savedDraftData.current.tnc
        delete savedDraftData.current.add_ons
        delete savedDraftData.current.premium_breakup
        delete savedDraftData.current.claims
        delete savedDraftData.current.benefit
        delete savedDraftData.current.common_deductible_content
      }
      if (!Object.hasOwnProperty.call(savedDraftData.current, 'add_on')) {
        savedDraftData.current.add_on = []
      }
      setEnableSave(true)
      updateDraftTimer.current = setTimeout(() => {
        updateDraftQuoteReq({
          body: {
            section: that.current.isReviewCall ? 'mv_quote_summary' : 'customer_data',
            sub_section: that.current.isReviewCall ? 'mv_quote_summary' : that.current.subSection,
            data: savedDraftData.current,
          },
          draftQuoteId: that.current.draftQuoteId,
        })
      }, timer || 3000)
    },
    [updateDraftQuoteReq, draftQuotationsDetailsData, policyDetails]
  )

  const handleSubmit = useCallback(
    (extraData = {}, timer) => {
      // Restore original field names before validation
      restoreFieldNames()

      const customerDoc = customerDocRef.current.validateFormValues()
      const customerName = customerNameRef.current.validateFormValues()
      const customerAddress = customerAddressRef.current.validateFormValues()
      const hardCopyAddress = hardCopyRef.current && hardCopyRef.current.validateHardCopyAddress()
      if (customerDoc && customerName && customerAddress) {
        savedDraftData.current = {
          ...draftQuotationsDetailsData.policy_details,
          ...savedDraftData.current,
          ...extraData,
          hard_copy_required: false,
        }
        if (hardCopyAddress?.hard_copy_required) {
          if (!hardCopyAddress.isValid) return
          delete hardCopyAddress.isValid
          savedDraftData.current = {
            ...savedDraftData.current,
            ...hardCopyAddress,
          }
        } else if (hardCopyAddress?.hard_copy_required === false) {
          savedDraftData.current = {
            ...savedDraftData.current,
            ...hardCopyAddress,
          }
        } else if (!Object.hasOwnProperty.call(savedDraftData.current, 'hard_copy_required')) {
          savedDraftData.current = {
            ...savedDraftData.current,
            hard_copy_sent_to: '',
            hard_copy_recipient: '',
            hard_copy_recipient_mobile: '',
            hard_copy_address: {},
            hard_copy_required: false,
            hard_copy_sent_to_name: '',
          }
        }
        if (that.current.isReviewCall) {
          savedDraftData.current = {
            ...policyDetails?.package_data,
            provider_branch: policyDetails?.package_data?.provider?.headquarter_branch,
            ...savedDraftData.current,
            ...savedDraftData.current.addons_data,
          }
          delete savedDraftData.current.tnc
          delete savedDraftData.current.add_ons
          delete savedDraftData.current.premium_breakup
          delete savedDraftData.current.claims
          delete savedDraftData.current.benefit
          delete savedDraftData.current.common_deductible_content
        }
        if (!Object.hasOwnProperty.call(savedDraftData.current, 'add_on')) {
          savedDraftData.current.add_on = []
        }
        if (savedDraftData.current.customer_address && savedDraftData.current.customer_data) {
          savedDraftData.current.customer_data.customer_address =
            savedDraftData.current.customer_address
        }
        setEnableSave(true)
        setLastActionType('saveDraft')
        updateDraftQuoteReq({
          body: {
            section: that.current.isReviewCall ? 'mv_quote_summary' : 'customer_data',
            sub_section: that.current.isReviewCall
              ? 'mv_quote_summary'
              : that.current.subSection
                ? that.current.subSection
                : 'customer_address',
            data: savedDraftData.current,
          },
          draftQuoteId: that.current.draftQuoteId,
        })
      }
    },
    [
      updateDraftQuoteReq,
      draftQuotationsDetailsData,
      policyDetails,
      restoreFieldNames,
      savedDraftData,
    ]
  )

  const handleChanges = useCallback(
    (data, subSection) => {
      // do ocr ktp
      if (subSection === 'customer_document') {
        if (Object.keys(data).includes('ktp_url')) {
          if (data.ktp_url) {
            // dont trigger when renewal
            if (
              ![MV_RENEWAL_STATUS.RENEWAL, MV_RENEWAL_STATUS.REACTIVATION].includes(
                draftQuotationsDetailsData?.policy_details?.renewal_status
              )
            ) {
              handleKtpOcr(data.ktp_url)
            }
          } else {
            // no update when ktp_url is empty
            return
          }
        }
      }
      that.current.formData = {
        ...that.current.formData,
        ...data,
      }
      that.current.subSection = subSection
      // validateTheFormForArrow(that.current.formData, subSection)
      if (['customer_information', 'customer_address'].includes(subSection)) {
        savedCustomerDataToGlobalStore({
          ...that.current.formData.customer_data,
          customer_address: {
            ...that.current.formData.customer_address,
          },
        })
      }
      handleSaveDraft(
        {
          ...data,
        },
        5000
      )
    },
    [handleKtpOcr, handleSaveDraft, savedCustomerDataToGlobalStore, draftQuotationsDetailsData]
  )

  const handleSaveClick = useCallback(() => {
    that.current.isSaveClick = true
    handleSaveDraft({}, 1, that.current.subSection)
  }, [handleSaveDraft])

  // refetch get latest data
  useEffect(() => {
    if (updateDraftQuotationStatus === 'success') {
      getDraftQuoteDetailsReq({ draftQuoteId: that.current.draftQuoteId })
    }
  }, [updateDraftQuotationStatus, getDraftQuoteDetailsReq])

  const handleBackClick = () => {
    history.push({
      pathname: `/motor_vehicle/form/${that.current.draftQuoteId}`,
    })
  }

  return (
    <Container
      title={LANG_STRINGS.mobil}
      loader={DRAFT_QUOTATIONS_DETAILS_LOADER || POST_DRAFT_POLICY_OCR_LOADER}
      className="bg-white"
      onBackClick={handleBackClick}
      onClose={() => {
        history.replace('/dashboard')
        that.current.removeEvent && that.current.removeEvent()
        ShowSnackbar.success({ text: LANG_STRINGS.quotationSaveMsg })
      }}
      onSaveClick={handleSaveClick}
      saveLoader={UPDATE_DRAFT_QUOTATION_LOADER}
      disabledSave={!enableSave}
      showSaveIcon
      showCloseIcon
      hideBottomTabs
      displayBackButton
      hideGuardianInfo
    >
      <PolicyStepsHeader
        stepsData={POLICY_STEPS}
        activeCount={4}
        prevActive={{ 1: true, 2: true, 3: true }}
      />
      <FixedTab iconUrl={USER} text="Isi Data Pelanggan" step={2} />
      <MVPolicyCustomerStyle>
        {policyDetails && (
          <>
            <div className="" id="ssg-container">
              <PageContainer>
                <form autoComplete="off" data-form-type="other" style={{ display: 'contents' }}>
                  <CustomerDocument
                    customerData={{
                      ...policyDetails.customer_data,
                      ktp_no: policyDetails?.ktp_no,
                      ktp_url: policyDetails?.ktp_url,
                    }}
                    ref={customerDocRef}
                    onChange={(data) => handleChanges(data, 'customer_document')}
                  />
                  <CustomerNameSection
                    customerData={policyDetails.customer_data}
                    ref={customerNameRef}
                    onChange={(data) => handleChanges(data, 'customer_information')}
                  />
                  <CustomerAddress
                    customerAddress={policyDetails.customer_address}
                    ref={customerAddressRef}
                    isAddressRequired={
                      policyDetails?.package_data?.extra_details?.customer_address_required
                    }
                    onChange={(data) => handleChanges(data, 'customer_address')}
                  />
                  {policyDetails?.package_data?.hard_copy_enabled && (
                    <div className="hard-copy-section">
                      <HardCopySection
                        ref={hardCopyRef}
                        policy={policyDetails}
                        onChange={(data) => handleChanges(data, 'hard_copy')}
                        preFilledData={hardCopyData}
                        isHideSendToPP={
                          policyDetails?.provider_branch?.tags
                            ? !policyDetails?.provider_branch?.tags.includes('HEADQUARTER')
                            : false
                        }
                        proposedFees={policyDetails?.proposed_fees}
                        isHardCopyRequired={policyDetails?.package_data?.always_charge_hard_copy}
                        isDisabledScroll={policyDetails?.provider_survey}
                      />
                    </div>
                  )}
                  {policyDetails?.provider_survey && (
                    <CustomerSurveyForm
                      ref={surveyFormRef}
                      data={{
                        providerCode: policyDetails?.provider_code,
                        startDate: policyDetails?.start_date,
                      }}
                    />
                  )}
                </form>
              </PageContainer>
            </div>
            <ButtonContainer>
              <Button variant="filled" onClick={() => handleSubmit()}>
                Bayar
              </Button>
            </ButtonContainer>
          </>
        )}
      </MVPolicyCustomerStyle>
      <QuoteSaveConfirmModal
        show={showQuoteConfirm}
        onClose={() => setShowQuoteConfirm(false)}
        page={`${LANG_STRINGS.mobil} Step 4`}
        message={LANG_STRINGS.quotationSaveMsg}
      />
    </Container>
  )
}

export default MVPolicyCustomerDataContainer
