import { ConfigUrl } from '../../../configs/url'

export const AGENT_ADDRESS_ACTIONS = {
  UPDATE_AGENT_ADDRESS_REQUEST: 'UPDATE_AGENT_ADDRESS_REQUEST',
  UPDATE_AGENT_ADDRESS: 'UPDATE_AGENT_ADDRESS'
}

export const updateAgentAddress = (payload) => ({
  type: AGENT_ADDRESS_ACTIONS.UPDATE_AGENT_ADDRESS_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.updateAgentAddress
  }
})
