import { LANG_STRINGS } from '../../../../../../../lang/index'
import CustomText from '../../../../../../../components/CustomText/index'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import {
  useState,
  useCallback,
  useMemo,
  useRef,
  Fragment,
  useImperativeHandle,
  forwardRef,
  useEffect,
} from 'react'
import { Error, Row } from '../../../../../../../commonStyle/index.style'
import { formatMoney } from '../../../../../../../helpers/utility'
import {
  getRecipientInfoFormV2,
  HARD_COPY_OPTION,
  REQUIRED_ADDRESS_FIELD,
  SEND_TO_AGENT,
  SEND_TO_ANOTHER,
  SEND_TO_CUSTOMER,
  SEND_TO_PASARPOLIS,
} from '../../../../../../../constants/hardCopy'
import Address from '../../../../../../../components/DynamicForm/Address'
import { Button } from '../../../../../../../components'
import { PASARPOLIS_ADDRESS } from '../../../../../../../constants/appConstants'
import { useGlobalContextValue } from '../../../../../../../contextProvider/GlobalContext/index'
import AgentAddressModal from '../../../../../../../components/AgentAddress/AddressModal'
import docSlider from '../../../../../../../helpers/docSlider'
import CustomCheckbox from '../../../../../../../components/CustomCheckbox'
import InputV2 from '../../../../../../../components/DynamicForm/components/InputV2'
import InputNumberV2 from '../../../../../../../components/DynamicForm/components/InputNumberV2'
import AutoSearchBottomSheetV2 from '../../../../../../../components/DynamicForm/components/AutoSearchBottomSheetV2'
import { HardCopyBrakdownContainer, HardCopyCheckContainer, TabContent } from './index.style'

function HardCopySection(
  {
    isCustomerForm,
    isHardCopyRequired,
    proposedFees = [],
    preFilledData = {},
    isHideSendToPP = false,
    onChange = () => {},
    isDisabledScroll,
  },
  parentRef
) {
  const [showHardCopyAddress, setShowHardCopyAddress] = useState(
    preFilledData.hard_copy_required || isHardCopyRequired
  )
  const [showAgentAddressModal, setShowAgentAddressModal] = useState(false)
  const [hardCopyRequired, setHardCopyRequired] = useState(
    !!preFilledData.hard_copy_required || isHardCopyRequired
  )
  const [errorMap, setErrorMap] = useState({})
  const [selectedHardCopyType, setSelectedHardCopyType] = useState(
    preFilledData.hard_copy_sent_to || ''
  )
  const [selectedTab, setSelectedTab] = useState(preFilledData.hard_copy_sent_to || '')
  const [{ customerData = {}, getAgentDetailData = {}, isStaffAgent }] = useGlobalContextValue()
  const hardCopyAnotherAddressRef = useRef()

  const getDataNonEmptyObject = (...objects) =>
    objects.find((obj) => obj && Object.keys(obj).length > 0) || {}

  const hardCopyAddressRef = useRef({
    hard_copy_address: getDataNonEmptyObject(
      preFilledData.hard_copy_address,
      preFilledData.customer_address,
      customerData.customer_address
    ),
    hard_copy_required: hardCopyRequired,
    hard_copy_sent_to: preFilledData.hard_copy_sent_to,
    hard_copy_sent_to_name:
      preFilledData.hard_copy_sent_to_name ||
      (HARD_COPY_OPTION.find((opt) => opt.id === preFilledData.hard_copy_sent_to) || {})?.name ||
      '',
    hard_copy_recipient: preFilledData.hard_copy_recipient,
    hard_copy_recipient_mobile: preFilledData.hard_copy_recipient_mobile,
  })
  const hardCopyRecipientRef = useRef({
    hard_copy_recipient: hardCopyAddressRef.current.hard_copy_recipient,
    hard_copy_recipient_mobile: hardCopyAddressRef.current.hard_copy_recipient_mobile,
  })
  const hardCopyAnotherRef = useRef({})
  const hardAgentAddressRef = useRef({})

  // const isHardCopyError = useMemo(() => {
  //   return (hardCopyRequired || isHardCopyRequired) && errorMap.hard_copy_recipient
  // }, [hardCopyRequired, errorMap, isHardCopyRequired])

  useImperativeHandle(parentRef, () => ({
    validateHardCopyAddress: () => {
      const body = {
        ...hardCopyAddressRef.current,
      }
      if (body.hard_copy_required || isHardCopyRequired) {
        if (!body.hard_copy_required && isHardCopyRequired) {
          body.hard_copy_required = isHardCopyRequired
        }
        let isValid = !!body.hard_copy_sent_to
        const error = {}
        if (!isValid) {
          error.hard_copy_sent_to = true
        }
        if (body.hard_copy_sent_to !== SEND_TO_PASARPOLIS) {
          let hardCopyAddress = body.hard_copy_address || {}
          if (body.hard_copy_sent_to === SEND_TO_ANOTHER) {
            const addressValidation = hardCopyAnotherAddressRef.current.validateAddressForm() || {}
            hardCopyAddress = {
              ...addressValidation,
              ...(addressValidation.city_code || {}),
              ...(addressValidation.province_code || {}),
            }
            body.hard_copy_address = hardCopyAddress
          }
          REQUIRED_ADDRESS_FIELD.forEach((field) => {
            if (!hardCopyAddress || !hardCopyAddress[field]) {
              isValid = false
              error[field] = true
            }
          })
          if (!body.hard_copy_recipient || !body.hard_copy_recipient_mobile) {
            isValid = false
            error.hard_copy_recipient = !body.hard_copy_recipient
            error.hard_copy_recipient_mobile = !body.hard_copy_recipient_mobile
          }
        }
        if (!isValid && Object.keys(error).length) {
          setErrorMap(error)
        }
        return {
          ...body,
          isValid,
        }
      }
      return {
        hard_copy_sent_to: '',
        hard_copy_sent_to_name: '',
        hard_copy_recipient: '',
        hard_copy_recipient_mobile: '',
        hard_copy_address: {},
        hard_copy_required: false,
        isValid: true,
      }
    },
  }))

  useEffect(() => {
    if (selectedTab !== SEND_TO_AGENT) return

    const agentAddress = getAgentDetailData?.address
    if (!agentAddress || !Object.keys(agentAddress).length) return

    const agentInfo = getRecipientInfo(SEND_TO_AGENT) || {}
    hardAgentAddressRef.current = agentAddress
    hardCopyRecipientRef.current = {
      hard_copy_recipient: agentInfo.hard_copy_recipient,
      hard_copy_recipient_mobile: agentInfo.hard_copy_recipient_mobile,
    }
    const updatedPayload = {
      hard_copy_address: agentAddress,
      hard_copy_recipient: agentInfo.hard_copy_recipient,
      hard_copy_recipient_mobile: agentInfo.hard_copy_recipient_mobile,
      hard_copy_sent_to: SEND_TO_AGENT,
      hard_copy_sent_to_name:
        (HARD_COPY_OPTION.find((opt) => opt.id === SEND_TO_AGENT) || {})?.name || '',
    }
    saveHardCopyToLocalRef(updatedPayload)
  }, [selectedTab, getAgentDetailData.address, getRecipientInfo, saveHardCopyToLocalRef])

  const hardCopyOptions = useMemo(() => {
    const hardCopyOpt = [...HARD_COPY_OPTION]
    // Remove the SEND_TO_AGENT option
    const filteredOptions = hardCopyOpt

    // const agentAddress = getAgentDetailData?.address

    // if ((isStaffAgent && isEmpty(agentAddress)) || isCustomerForm) {
    //   // if its a customer form or staff login
    //   // then remove the send_to_agent option
    //   filteredOptions.splice(1, 1)
    // }
    // if (isHideSendToPP) {
    //   filteredOptions.splice(-1, 1)
    // }
    return filteredOptions
  }, [])

  const saveHardCopyToLocalRef = useCallback((payload) => {
    hardCopyAddressRef.current = {
      ...hardCopyAddressRef.current,
      ...payload,
    }
  }, [])

  const handleSwitch = useCallback(() => {
    setShowHardCopyAddress((prevValue) => !prevValue)
    setHardCopyRequired((prevValue) => !prevValue)
    setSelectedHardCopyType('')
    saveHardCopyToLocalRef({
      hard_copy_required: !hardCopyRequired,
      hard_copy_sent_to: '',
      hard_copy_sent_to_name: '',
    })

    const hardCopyData = {
      hard_copy_required: !showHardCopyAddress,
      hard_copy_address: getDataNonEmptyObject(
        preFilledData.hard_copy_address || preFilledData?.customer_address
      ),
    }

    // clear the data if uncheck hard copy
    if (!showHardCopyAddress === false) {
      hardCopyData.hard_copy_address = {}
      hardCopyData.hard_copy_recipient = ''
      hardCopyData.hard_copy_recipient_mobile = ''
      hardCopyData.hard_copy_sent_to = ''
      hardCopyData.hard_copy_sent_to_name = ''
      setSelectedTab('')
    }

    onChange({
      ...hardCopyData,
    })
  }, [saveHardCopyToLocalRef, hardCopyRequired, showHardCopyAddress, preFilledData, onChange])

  const getRecipientMap = useCallback((name, mobile, address) => {
    return {
      hard_copy_recipient: name,
      hard_copy_address: address,
      hard_copy_recipient_mobile: mobile,
    }
  }, [])

  const getRecipientInfo = useCallback(
    (id) => {
      switch (id) {
        case SEND_TO_CUSTOMER:
          return getRecipientMap(
            customerData.customer_name || customerData.name,
            customerData.mobile_no,
            getDataNonEmptyObject(
              customerData.customer_address,
              preFilledData?.customer_address,
              preFilledData?.hard_copy_address
            )
          )
        case SEND_TO_AGENT:
          return getRecipientMap(
            isStaffAgent ? getAgentDetailData?.parent_name : getAgentDetailData?.name,
            isStaffAgent ? getAgentDetailData?.parent_phone_no : getAgentDetailData?.phone_no,
            getAgentDetailData.address
          )
        default:
          return {
            hard_copy_recipient: '',
            hard_copy_recipient_mobile: '',
          }
      }
    },
    [
      getRecipientMap,
      customerData.customer_name,
      customerData.name,
      customerData.mobile_no,
      customerData.customer_address,
      preFilledData,
      isStaffAgent,
      getAgentDetailData?.parent_name,
      getAgentDetailData?.name,
      getAgentDetailData?.parent_phone_no,
      getAgentDetailData?.phone_no,
      getAgentDetailData.address,
      getDataNonEmptyObject,
    ]
  )

  const handleTabChange = useCallback(
    (selectedOption) => {
      if (!selectedOption || !selectedOption.id) return

      const tabId = selectedOption.id
      setSelectedTab(tabId)
      setSelectedHardCopyType(tabId)
      const option = hardCopyOptions.find((opt) => opt.id === tabId)
      if (option) {
        // Reset the form state completely
        hardCopyRecipientRef.current = {
          hard_copy_recipient: '',
          hard_copy_recipient_mobile: '',
        }

        if (option.id === SEND_TO_CUSTOMER) {
          const customerInfo = getRecipientInfo(option.id)
          hardCopyRecipientRef.current = {
            ...customerInfo,
            hard_copy_recipient: customerInfo.hard_copy_recipient || '',
            hard_copy_recipient_mobile: customerInfo.hard_copy_recipient_mobile || '',
          }
        }

        if (option.id === SEND_TO_AGENT) {
          const customerInfo = getRecipientInfo(option.id)
          hardCopyRecipientRef.current = {
            ...customerInfo,
            hard_copy_recipient: customerInfo.hard_copy_recipient || '',
            hard_copy_recipient_mobile: customerInfo.hard_copy_recipient_mobile || '',
          }
        }

        setErrorMap({})
        let anotherAddress = {}
        if (isDisabledScroll) {
          docSlider.enable(false)
        }

        if (option.id === SEND_TO_ANOTHER) {
          anotherAddress = {
            ...hardCopyAnotherRef.current,
          }
        } else if (option.id === SEND_TO_PASARPOLIS) {
          anotherAddress = {
            hard_copy_address: PASARPOLIS_ADDRESS,
            hard_copy_recipient: '',
            hard_copy_recipient_mobile: '',
            is_hard_copy_recipient: false,
          }
        }
        saveHardCopyToLocalRef({
          ...anotherAddress,
          ...hardCopyRecipientRef.current,
          hard_copy_sent_to: option.id,
          hard_copy_sent_to_name:
            (HARD_COPY_OPTION.find((opt) => opt.id === option.id) || {})?.name || '',
        })

        onChange({
          ...anotherAddress,
          ...hardCopyRecipientRef.current,
          hard_copy_sent_to: option.id,
          hard_copy_sent_to_name:
            (HARD_COPY_OPTION.find((opt) => opt.id === option.id) || {})?.name || '',
        })
      }
    },
    [hardCopyOptions, getRecipientInfo, isDisabledScroll, saveHardCopyToLocalRef, onChange]
  )

  const handleChangeInput = useCallback(
    (e, name) => {
      // handle to store recipient info local first
      const value = e?.target ? e.target.value : e
      hardCopyRecipientRef.current = {
        ...hardCopyRecipientRef.current,
        [name]: value,
      }
      // Save immediately to ensure data is updated
      saveHardCopyToLocalRef({
        ...hardCopyRecipientRef.current,
      })
    },
    [saveHardCopyToLocalRef]
  )

  const handleOnBlur = useCallback(
    (name) => {
      // Save the current state
      saveHardCopyToLocalRef({
        ...hardCopyRecipientRef.current,
      })
    },
    [saveHardCopyToLocalRef]
  )

  const handleAgentAddressSave = useCallback((address) => {
    hardAgentAddressRef.current = address
    setShowAgentAddressModal(false)
  }, [])

  const handleCloseAgentAddressModal = useCallback(() => {
    setShowAgentAddressModal(false)
  }, [])

  const handleFillAddress = useCallback(() => {
    setShowAgentAddressModal(true)
  }, [])

  const renderInputElement = useCallback(
    ({
      type,
      index,
      name,
      label,
      defaultValue,
      title,
      required,
      placeholder,
      disabled,
      className,
    }) => {
      let children = null
      if (type === 'inputV2') {
        children = (
          <InputV2
            placeholder={placeholder}
            name={name}
            title={title}
            defaultValue={defaultValue}
            errorField={errorMap[name] ? name : ''}
            onChange={(e) => handleChangeInput(e, name)}
            onBlur={() => handleOnBlur(name)}
            disabled={disabled}
            displayBorder
            maxlength={50}
            className={className}
            bottom="1em"
          />
        )
      } else if (type === 'inputNumberV2') {
        children = (
          <InputNumberV2
            placeholder={title}
            value={defaultValue}
            disabled={disabled}
            onChange={(values) => handleChangeInput(values.value, name)}
            onBlur={() => handleOnBlur(name)}
            className={className}
            bottom="1em"
          />
        )
      }
      return (
        <Fragment key={name}>
          {/* <FormItemLabel
          title={label}
          required={required}
        /> */}
          {children}
        </Fragment>
      )
    },
    [handleChangeInput, handleOnBlur, errorMap]
  )

  const renderRecipientForm = useCallback(
    (recipientName = '', recipientMobile = '', isDisabledFields = false) => {
      // For "Send to Another", always use empty values if not explicitly provided
      const shouldUseRefValues = selectedTab !== SEND_TO_ANOTHER
      const mapData = {
        hard_copy_recipient: shouldUseRefValues
          ? hardCopyRecipientRef.current.hard_copy_recipient || recipientName
          : recipientName,
        hard_copy_recipient_mobile: shouldUseRefValues
          ? hardCopyRecipientRef.current.hard_copy_recipient_mobile || recipientMobile
          : recipientMobile,
      }
      const recipientForm = getRecipientInfoFormV2(mapData, isDisabledFields)
      return recipientForm.map((form, index) =>
        renderInputElement({ ...form, key: `${form.name}-${selectedTab}-${index}` })
      )
    },
    [renderInputElement, selectedTab]
  )

  const renderCustomerAddress = useCallback(() => {
    let addressArr = []
    // source if the first state is uncheck and will put the customer data after choose hard copy sent to
    const customerAddress = getDataNonEmptyObject(
      customerData?.customer_address,
      preFilledData?.customer_address,
      preFilledData?.hard_copy_address
    )

    const isHasCustomerAddress =
      customerAddress?.address && customerAddress.city_name && customerAddress.province_name

    if (isHasCustomerAddress) {
      addressArr = [
        customerAddress.address,
        `${customerAddress.city_name} ${customerAddress.postal_code}`,
        customerAddress.province_name,
      ]
    }

    return (
      <div className="hard-copy-address">
        <InputV2
          placeholder="Masukkan nama penerima"
          name="hard_copy_recipient"
          title={LANG_STRINGS.recipientName}
          defaultValue={
            customerData.customer_name ||
            customerData.name ||
            preFilledData?.hard_copy_recipient ||
            ''
          }
          bottom="1em"
          disabled
        />
        <InputV2
          placeholder="Masukkan nomor penerima"
          name="hard_copy_recipient_mobile"
          title={LANG_STRINGS.activeMobileNumber}
          defaultValue={customerData.mobile_no || preFilledData?.hard_copy_recipient_mobile || ''}
          bottom="1em"
          disabled
        />
        <InputV2
          placeholder="Masukkan alamat"
          name="hard_copy_address"
          title="Alamat"
          defaultValue={addressArr.join(', ')}
          textArea
          disabled
        />
      </div>
    )
  }, [customerData, renderRecipientForm])

  const renderAgentAddress = useCallback(() => {
    const agentAddress = getAgentDetailData.address
    if (!Object.keys(agentAddress).length) {
      return (
        <CustomText
          size="13px"
          color={AgentColorPallette.regular}
          className="hard-copy-address"
          weight={600}
        >
          {LANG_STRINGS.addressDataNotComplete}.
          <CustomText
            size="13px"
            color={AgentColorPallette.goldDarker}
            weight={700}
            onClick={handleFillAddress}
          >
            {LANG_STRINGS.fillYourAddress}.
          </CustomText>
        </CustomText>
      )
    }

    const agentAddressMap = [
      agentAddress.address,
      `${agentAddress.city_name} ${agentAddress.postal_code}`,
      agentAddress.province_name,
    ]
    return (
      <div className="hard-copy-address">
        {renderRecipientForm(
          isStaffAgent ? getAgentDetailData?.parent_name : getAgentDetailData?.name,
          isStaffAgent ? getAgentDetailData?.parent_phone_no : getAgentDetailData?.phone_no,
          true
        )}
        <InputV2
          placeholder="Masukkan alamat"
          name="hard_copy_address"
          title="Alamat"
          defaultValue={agentAddressMap.join(', ')}
          textArea
          disabled
        />
        {/* {
          !isStaffAgent &&
            <Button
              justifyContent='center'
              width='80px'
              className='change-agent-address-btn'
              onClick={handleFillAddress}
            >
              {LANG_STRINGS.changeAddress}
            </Button>
        } */}
      </div>
    )
  }, [getAgentDetailData, handleFillAddress, renderRecipientForm, isStaffAgent])

  const renderAnotherAddress = useCallback(() => {
    return (
      <div className="hard-copy-address">
        {renderRecipientForm()}
        <Address
          key={`address-form-${selectedTab}`}
          ref={hardCopyAnotherAddressRef}
          addressType="hard-copy-address"
          name="hard_copy_address"
          defaultValue={
            preFilledData.hard_copy_sent_to === SEND_TO_ANOTHER
              ? hardCopyAddressRef.current.hard_copy_address
              : {}
          }
          designV2
        />
      </div>
    )
  }, [renderRecipientForm, preFilledData, selectedTab])

  const renderOptionChild = useCallback(
    ({ id, name }) => {
      switch (id) {
        case SEND_TO_CUSTOMER:
          return renderCustomerAddress(name)
        case SEND_TO_AGENT:
          return renderAgentAddress(name)
        case SEND_TO_ANOTHER:
          return renderAnotherAddress(name)
        default:
          return (
            <CustomText
              size="13px"
              color={AgentColorPallette.regular}
              className="hard-copy-address"
            >
              {PASARPOLIS_ADDRESS.address}
            </CustomText>
          )
      }
    },
    [renderCustomerAddress, renderAnotherAddress, renderAgentAddress]
  )

  return (
    <>
      <CustomText color={AgentColorPallette.black} size="1em" top="1em" bottom="0.5em" weight={700}>
        {LANG_STRINGS.printPolicy}
      </CustomText>
      <HardCopyCheckContainer>
        <Row justify="space-between" align="center">
          <CustomText color={AgentColorPallette.blackGrey} size="0.85rem">
            {LANG_STRINGS.selectThisOptionIfYouWantHardCopy}
          </CustomText>
          <CustomCheckbox
            id="addons"
            color={AgentColorPallette.black}
            isChecked={showHardCopyAddress}
            onChange={handleSwitch}
            disabled={isHardCopyRequired}
          />
        </Row>
      </HardCopyCheckContainer>
      {showHardCopyAddress && proposedFees.length > 0 && (
        <HardCopyBrakdownContainer>
          <CustomText color={AgentColorPallette.regular} size="0.9rem" weight={700} bottom="0.5rem">
            {LANG_STRINGS.additionalFeesApplied}
          </CustomText>
          {proposedFees?.map((fee, index) => (
            <Row justify="space-between" align="center" key={fee?.key || index}>
              <CustomText color={AgentColorPallette.regular} size="0.85rem" bottom="0.5rem">
                {fee?.label}
              </CustomText>
              <CustomText color={AgentColorPallette.regular} size="0.85rem" bottom="0.5rem">
                {formatMoney(fee.value, 0)}
              </CustomText>
            </Row>
          ))}
        </HardCopyBrakdownContainer>
      )}
      {showHardCopyAddress && (
        <>
          <AutoSearchBottomSheetV2
            title="Tujuan Pengiriman"
            name="hard_copy_sent_to"
            data={hardCopyOptions}
            displayKey="name"
            dataKey="id"
            defaultValue={hardCopyOptions.find((opt) => opt.id === selectedTab) || {}}
            onChange={handleTabChange}
            error={errorMap.hard_copy_sent_to ? LANG_STRINGS.required : ''}
            hideSearchBar
            margin
          />
          <TabContent>{selectedTab && renderOptionChild({ id: selectedTab })}</TabContent>
        </>
      )}
      {showAgentAddressModal && (
        <AgentAddressModal
          show={showAgentAddressModal}
          onClose={handleCloseAgentAddressModal}
          onAgentAddressSave={handleAgentAddressSave}
        />
      )}
    </>
  )
}

export default forwardRef(HardCopySection)
