import { StyleContainer } from './index.style'

function InformationBox({ type, title, content }) {
  return (
    <StyleContainer type={type} data-testid="information-box">
      {title && (
        <div className="info-box__title" data-testid="information-box-title">
          {title}
        </div>
      )}
      <div
        className="info-box__content"
        data-testid="information-box-content"
        dangerouslySetInnerHTML={{ __html: content }}
      />
    </StyleContainer>
  )
}

export default InformationBox
