import { useState, useEffect } from 'react'
import CustomCheckbox from '../../../CustomCheckbox'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { StyleContainer } from './index.style'

function Checkbox({ name, title, description, defaultValue, onChange, error, required, disabled }) {
  const toChecked = (val) => val === 'true' || val === true

  const [checked, setChecked] = useState(toChecked(defaultValue))

  useEffect(() => {
    if (defaultValue !== undefined && defaultValue !== null) {
      setChecked(toChecked(defaultValue))
    }
  }, [defaultValue])

  const handleToggle = () => {
    if (disabled) return
    const next = !checked
    setChecked(next)
    onChange?.({ name, value: next ? true : false })
  }

  return (
    <StyleContainer data-testid="checkbox-group">
      <div
        className={`checkbox__card ${checked ? 'checked' : ''} ${disabled ? 'disabled' : ''}`}
        onClick={handleToggle}
        data-testid="checkbox-card"
      >
        <div className="checkbox__card-content">
          <span className={`checkbox__card-label ${disabled ? 'disabled' : ''}`}>{title}</span>
          {description && <span className="checkbox__card-description">{description}</span>}
        </div>
        <div className="checkbox__control">
          <CustomCheckbox
            isChecked={checked}
            onChange={handleToggle}
            bgColor={AgentColorPallette.darkCharcoal}
            color={AgentColorPallette.white}
            data-testid="checkbox-input"
          />
        </div>
      </div>
      {error && (
        <div className="checkbox__error" data-testid="checkbox-error">
          {error}
        </div>
      )}
    </StyleContainer>
  )
}

export default Checkbox
