import Heading from '../../../../../../../../components/Heading'
import { CustomerSurveyFormStyle } from './index.style'
import { LANG_STRINGS } from '../../../../../../../../lang/index'
import { useEffect, useRef, forwardRef, useImperativeHandle } from 'react'
import { useGetSurveyForm } from '../../../../../../../../state/commonState/hooks/useCommonContext'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../../../components/ShowNotification'
import QuestionsForm from '../components/QuestionsForm'

function CustomerSurveyFormContainer ({ data = {} }, parentRef) {
  const [{ getSurveyFormData = {} }, getSurveyFormRequest] = useGetSurveyForm()
  const [{ GET_SURVEY_FORM_ERROR, getSurveyFormStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const that = useRef({
    isSurveyFormCall: false
  })
  const surveyQueRef = useRef()

  useImperativeHandle(parentRef, () => ({
    validateForm: () => {
      return surveyQueRef.current.getQuestionsAns()
    }
  }))

  useEffect(() => {
    if (GET_SURVEY_FORM_ERROR && getSurveyFormStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getSurveyFormStatus
      })
      resetError(['getSurveyFormStatus'])
    }
  }, [
    getSurveyFormStatus, GET_SURVEY_FORM_ERROR, resetError
  ])

  useEffect(() => {
    if (!that.current.isSurveyFormCall && data?.providerCode) {
      that.current.isSurveyFormCall = true
      getSurveyFormRequest({
        query: {
          provider_code: data?.providerCode,
          policy_start_date: data?.startDate
        }
      })
    }
  }, [getSurveyFormRequest, data])

  return (
    <CustomerSurveyFormStyle>
      <Heading
        title={LANG_STRINGS.vehicleSurvey}
      />
      {
        getSurveyFormData?.questions?.map(surveyForm => (
          <QuestionsForm
            key={surveyForm.id}
            surveyQuestion={surveyForm}
            ref={surveyQueRef}
          />
        ))
      }
    </CustomerSurveyFormStyle>
  )
}

export default forwardRef(CustomerSurveyFormContainer)
