import { forwardRef, useRef, useCallback, useEffect, useState } from 'react'
import isEmpty from 'lodash/isEmpty'
import DynamicForm from '../../../../../../../components/DynamicForm'
import { getCustomerNameForm } from '../../constants'

function CustomerNameSection({ customerData = {}, onChange }, parentRef) {
  const dataRef = useRef({})
  const [rerender, setRerender] = useState(1)

  useEffect(() => {
    const hasData = !isEmpty(customerData)
    const isDataRefEmpty = isEmpty(dataRef.current)

    const hasFieldChanged =
      dataRef.current.name !== customerData.name ||
      dataRef.current.email !== customerData.email ||
      dataRef.current.mobile_no !== customerData.mobile_no

    if (hasData && (isDataRefEmpty || hasFieldChanged)) {
      dataRef.current = { ...customerData }
    }
  }, [customerData])

  useEffect(() => {
    if (typeof customerData.name === 'string') {
      // rerender when name is changes, action auto fill ocr
      setRerender((prev) => prev + 1)
    }
  }, [customerData.name])

  const handleChange = useCallback(
    (data) => {
      dataRef.current = {
        ...dataRef.current,
        ...data,
      }
      onChange({
        customer_data: {
          ...dataRef.current,
        },
      })
    },
    [onChange]
  )

  return (
    <>
      <DynamicForm
        key={rerender.toString()}
        form={getCustomerNameForm(customerData)}
        ref={parentRef}
        onChange={handleChange}
        formName="customerNameForm"
        isValidateOnChange
        isDocSlider
      />
    </>
  )
}

export default forwardRef(CustomerNameSection)
