export const gTagOnSaveDraft = (entry) => {
  // this function fires google tag on click install to tag manager
  // eslint-disable-next-line no-undef
  window.dataLayer && window.dataLayer.push({
    event: 'draftQuoteSaved',
    entry_from_var: entry
  })
}

export const gTagOnSaveDraftQuoteClose = (entry) => {
  // this function fires google tag on click install to tag manager
  // eslint-disable-next-line no-undef
  window.dataLayer && window.dataLayer.push({
    event: 'draftQuoteSavedClose',
    entry_from_var: entry
  })
}
