import { QuestionFormStyle } from './index.style'
import {
  useCallback, useState, Fragment, useRef,
  useImperativeHandle, forwardRef, useEffect
} from 'react'
import { CustomText } from '../../../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../../../configs/colorPallete'
import { Error, Row } from '../../../../../../../../../commonStyle/index.style'
import Switch from '../../../../../../../../../components/Switch/index'
import Address from '../../../../../../../../../components/DynamicForm/Address'
import RadioWithChildren from '../../../../../../../../../components/DynamicForm/components/RadioWithChildren/index'
import DateTimePicker from '../../../../../../../../../components/DynamicForm/components/DateTimerPicker'
import { isEmpty } from 'lodash'
import { LANG_STRINGS } from '../../../../../../../../../lang'

function QuestionsForm ({ surveyQuestion }, parentRef) {
  const [answers, setAnswers] = useState({})
  const [errorMap, setErrorMap] = useState({})
  const addressRef = useRef()
  const answersRef = useRef({})
  const that = useRef({})

  useEffect(() => {
    const el = document.getElementById('questionsFormView')
    el.addEventListener('focusin', (e) => {
      e.preventDefault()
      e.stopPropagation()
    })
  }, [])

  const validateFormData = useCallback((questions = []) => {
    let isValidate = false
    for (const que of questions) {
      if (que.is_required) {
        let queAns = answers[que.id] || (que.question_type === 'TYPE_CHECKBOX_SLIDER' ? ({ value: 'False' }) : null)
        if ((que.question_type === 'TYPE_ADDRESS') && that.current.address) {
          queAns = {}
          let value = {}
          for (const key in that.current.address) {
            const item = that.current.address[key]
            if (['city_code', 'province_code'].includes(key)) {
              value = {
                ...value,
                ...item
              }
            } else {
              value[key] = item
            }
          }
          queAns = {
            value
          }
        }
        if (!queAns) {
          // isValid = false
          isValidate = false
          return isValidate
        }
        answersRef.current = {
          ...answersRef.current,
          [que.id]: {
            head: que.question,
            ...queAns
          }
        }
        isValidate = true
        const queOptions = que?.question_option || []
        for (const queOption of queOptions) {
          if ((queOption.title === queAns.value) || (queOption.title === 'False')) {
            // check only for selected question and answer
            const isValidOptions = validateFormData(queOption.questions)
            isValidate = isValidate && isValidOptions
          }
        }
        if (!isValidate) {
          return false
        }
      }
    }
    return isValidate
  }, [answers])

  useImperativeHandle(parentRef, () => ({
    getQuestionsAns: () => {
      // let isValid = false
      const address = addressRef.current && addressRef.current.validateAddressForm()
      that.current.address = address
      const isValid = validateFormData([surveyQuestion])
      const ansData = {
        address,
        isValid,
        answer: {
          ...answersRef.current
        }
      }
      if (!isValid) {
        if (isEmpty(ansData.answer)) {
          setErrorMap({
            form: true
          })
        }
      }
      return ansData
    }
  }))

  const handleAnsChange = useCallback((id, value) => {
    setAnswers(prevAns => {
      return {
        ...prevAns,
        [id]: {
          value
        }
      }
    })
  }, [])

  const renderQuestions = useCallback((question) => {
    switch (question.question_type) {
      case 'TYPE_RADIO_VERTICAL':
        return (
          <div
            className='vertical-radio-style'
            key={question.id}
          >
            {
              question.question_option.map((vop, index) => (
                <RadioWithChildren
                  isBtmBorder={index < (question.question_option.length - 1)}
                  key={vop.title}
                  name={vop.title}
                  data={{
                    id: vop.title
                  }}
                  selected={answers[question.id]?.value}
                  onChange={(op) => handleAnsChange(
                    question.id,
                    op.id,
                    question.question_type,
                    question.is_required
                  )}
                  label={vop?.title}
                  error={errorMap.form && LANG_STRINGS.required}
                >
                  <div className='v-option'>
                    {
                        vop?.description &&
                          <CustomText
                            size='13px'
                            bottom='0.5rem'
                            color={AgentColorPallette.regular}
                            dangerouslySetInnerHTML={{
                              __html: vop?.description
                            }}
                          />
                    }
                    {
                      vop.questions.map((qp) => {
                        if (['TYPE_CHECKBOX_SLIDER'].includes(qp.question_type)) {
                          return (
                            renderQuestions(qp)
                          )
                        }
                        return (
                          <div className='render-sub-questions' key={`sub_ques_${qp.id}`}>
                            {renderQuestions(qp)}
                          </div>
                        )
                      })
                    }
                  </div>
                </RadioWithChildren>
              ))
            }
          </div>
        )
      case 'TYPE_ADDRESS':
        return (
          <div
            className='question'
            key={question.id}
            data-qid={question.id}
            data-isReq={question.is_required}
            data-type={question.question_type}
          >
            <Address
              ref={addressRef}
              name={question.id}
              onChange={(val) => { handleAnsChange(question.id, val, question.question_type, question.is_required) }}
            />
          </div>
        )
      case 'TYPE_CHECKBOX_SLIDER':
      {
        return (
          <div
            key={question.id}
            data-qid={question.id}
            data-isReq={question.is_required}
            data-type={question.question_type}
          >
            <Row justify='space-between' align='center' className='checkbox-slider-question'>
              <CustomText
                size='13px'
                color={AgentColorPallette.regular}
                top='0'
              >
                {question.question}
              </CustomText>
              <Switch
                isChecked={answers[question.id]?.value === 'True'}
                onChange={() => handleAnsChange(
                  question.id,
                  answers[question.id]?.value === 'True' ? 'False' : 'True',
                  question.question_type,
                  question.is_required
                )}
              />
            </Row>
            {
              (answers[question.id]?.value !== 'True') && (
                question.question_option.map((qp) => {
                  if (qp.questions) {
                    const elm = []
                    for (const que of qp.questions) {
                      elm.push(renderQuestions(que))
                    }
                    return (
                      <div className='render-sub-questions' key={`sub_ques_in_${qp.id}`}>
                        {elm}
                      </div>
                    )
                  }
                  return null
                })
              )
            }
          </div>
        )
      }
      case 'TYPE_DATE_TIME':
      {
        const dateProps = {
          type: 'datetime-local',
          className: 'datetimerpicker',
          value: answers[question.id]?.value,
          onChange: (e) => { handleAnsChange(question.id, e.target.value, question.question_type, question.is_required) }
        }
        if (question?.constraints?.max_value) {
          dateProps.max = question.constraints.max_value
        }
        if (question?.constraints?.min_value) {
          dateProps.min = question.constraints.min_value
        }
        return (
          <div
            className='question'
            key={question.id}
            data-qid={question.id}
            data-isReq={question.is_required}
            data-type={question.question_type}
            data-weekday={question?.constraints?.restrict_to_weekdays}
          >
            <DateTimePicker
              onChange={(data) => handleAnsChange(question.id, data[question.id])}
              maxDate={question?.constraints?.max_value}
              minDate={question?.constraints?.min_value}
              invalid={question?.constraints?.restrict_to_weekdays ? 'weekends' : ''}
              minTime='09:00'
              maxTime='15:00'
              name={question.id}
            />
          </div>
        )
      }
      default:
    }
  }, [handleAnsChange, answers, errorMap])

  return (
    <QuestionFormStyle id='questionsFormView'>
      {
        surveyQuestion && (
          <Fragment key={`survey_qus_${surveyQuestion.id}`}>
            <CustomText
              size='0.85em'
              color={AgentColorPallette.regular}
              bottom='1rem'
            >
              {surveyQuestion.question}
            </CustomText>
            {
              renderQuestions(surveyQuestion)
            }
          </Fragment>
        )
      }
      {
        errorMap.form && (
          <Error>{LANG_STRINGS.required}</Error>
        )
      }
    </QuestionFormStyle>
  )
}

export default forwardRef(QuestionsForm)
