import { forwardRef, useImperativeHandle, useRef } from 'react'
import { CommonContextProvider } from '../../../../../../../contextProvider/CommonContext'
import CustomerSurveyFormContainer from './container'

function CustomerSurveyForm (props, ref) {
  const formRef = useRef()
  useImperativeHandle(ref, () => ({
    validateForm: () => formRef.current.validateForm()
  }))

  return (
    <CommonContextProvider>
      <CustomerSurveyFormContainer {...props} ref={formRef} />
    </CommonContextProvider>
  )
}

export default forwardRef(CustomerSurveyForm)
