import { usePostDraftPolicyOcr } from '../../../state/hooks/usePolicyState'
import { useEffect, useState } from 'react'
import { FILE_TYPE_OCR } from '../constants'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import {
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'

export const useOcrKtpService = ({
  draftId = '',
  handleSaveDraftKtp = () => {},
  handleErrorOcr = () => {},
}) => {
  const [lastProcessedKtpUrl, setLastProcessedKtpUrl] = useState(null)
  const [ktpOcrData, setKtpOcrData] = useState({})
  const [isOcrKtpDone, setIsOcrKtpDone] = useState(false)
  const { resetError } = useResetError()

  const [{ postDraftPolicyOcrData }, postDraftPolicyOcrRequest] =
    usePostDraftPolicyOcr()
  const [{ postDraftPolicyOcrErrorData }] = useErrorContextValue()

  const handleKtpOcr = (ktpkUrl) => {
    resetError(['postDraftPolicyOcrErrorData'])
    if (lastProcessedKtpUrl === ktpkUrl) {
      return
    }
    setLastProcessedKtpUrl(ktpkUrl)
    postDraftPolicyOcrRequest({
      draftId,
      body: {
        document_url: ktpkUrl,
        file_type: FILE_TYPE_OCR.KTP,
      },
    })
    setIsOcrKtpDone(true)
  }

  useEffect(() => {
    if (postDraftPolicyOcrData?.success) {
      if (postDraftPolicyOcrData.data.file_type === FILE_TYPE_OCR.KTP) {
        if (
          ktpOcrData?.nik !== postDraftPolicyOcrData?.data?.nik ||
          ktpOcrData?.name !== postDraftPolicyOcrData?.data?.name
        ) {
          setKtpOcrData(postDraftPolicyOcrData?.data)
          handleSaveDraftKtp(postDraftPolicyOcrData?.data)
        }
      }
    }
  }, [
    handleSaveDraftKtp,
    ktpOcrData,
    postDraftPolicyOcrData?.data,
    postDraftPolicyOcrData?.success,
  ])

  useEffect(() => {
    if (!postDraftPolicyOcrErrorData?.success) {
      // show error by type
      if (postDraftPolicyOcrErrorData?.data?.file_type === FILE_TYPE_OCR.KTP) {
        handleErrorOcr(postDraftPolicyOcrErrorData)
        ShowSnackbar.error({
          visible: true,
          text: postDraftPolicyOcrErrorData?.error,
        })
      }
    }
  }, [postDraftPolicyOcrErrorData?.success])

  return {
    handleKtpOcr,
    ktpOcrData,
    isOcrKtpDone,
  }
}
