import { useState, useCallback, useEffect, forwardRef, useImperativeHandle } from 'react'
import { CustomText } from '../../..'
import { Error, Row } from '../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import FormItemLabel from '../FormItemLabel'
import { RadioInputStyle, RadioElementStyle } from './index.style'
import { SELECTION_ARROW } from '../../../../images/imageUrl'

function RadioInput ({
  title, required, name, data = [], disabled, disabledKey,
  onChange = () => {}, onClick = () => {}, defaultSelected, error, noBorder
}, parentRef) {
  const [selected, setSelected] = useState(defaultSelected)

  useImperativeHandle(parentRef, () => ({
    resetSelected: (value) => setSelected(value)
  }))

  useEffect(() => {
    if (!selected && defaultSelected) {
      setSelected(defaultSelected)
      const item = data.find((elm) => {
        if ((elm === defaultSelected) || (elm.id === defaultSelected)) {
          return true
        }
        return false
      })
      onChange(item)
    }
  }, [data, selected, onChange, defaultSelected])

  const handleOnChange = useCallback((item) => {
    setSelected(item.id)
    // pass the selected item to parent
    if (onChange) {
      onChange({
        name,
        ...item
      })
    }
  }, [name, onChange])

  const renderRadioLabel = useCallback((item) => {
    return (
      <Row align='center' justify='space-between' className='radio-label-text'>
        <div>
          <div className='radio-label-title'>
            {item.label}
          </div>
          {
            item.subText && (
              <CustomText
                size='0.65em'
                top='4px'
                weight={700}
                color={AgentColorPallette.fontGrey}
              >
                {item.subText}
              </CustomText>
            )
          }
        </div>
        {
          item.isArrow && (
            <img src={SELECTION_ARROW} alt='' />
          )
        }
      </Row>
    )
  }, [])

  const renderRadioElement = useCallback((item, index) => {
    // render the radio input element
    return (
      <RadioElementStyle
        key={item.id}
        disabled={disabled || (disabledKey === item.id)}
        borderColor={error && AgentColorPallette.errorDark}
        isSubText={!!item.subText}
        noBorder={noBorder}
      >
        <label
          className='radio-container'
        >
          {renderRadioLabel(item)}
          <input
            type='radio'
            checked={item.id === selected}
            name={name}
            value={item.value}
            onClick={
              () => onClick(item.id)
            }
            onChange={(e) => {
              if (disabled || (disabledKey === item.id)) return false
              handleOnChange(item)
            }}
            disabled={disabled || (disabledKey === item.id)}
          />
          <span className='checkmark' />
        </label>
      </RadioElementStyle>
    )
  }, [
    disabled, handleOnChange, name, selected,
    disabledKey, renderRadioLabel, error, onClick, noBorder
  ])

  return (
    <RadioInputStyle>
      <FormItemLabel
        title={title}
        required={required}
      />
      <div className='radio-items'>
        {
          data.map(renderRadioElement)
        }
      </div>
      {
        error && <Error>{error}</Error>
      }
    </RadioInputStyle>
  )
}

export default forwardRef(RadioInput)
