import { Component } from 'react'
import PropTypes from 'prop-types'
import { SwitchStyle } from './index.style'

class Switch extends Component {
  static propTypes = {
    onChange: PropTypes.func,
    id: PropTypes.string,
    disabled: PropTypes.bool,
    isChecked: PropTypes.bool
  }

  constructor (props) {
    super(props)
    this.state = {
      isChanged: false
    }
  }

  handleChange = (e) => {
    this.setState({
      isChanged: e.currentTarget.checked
    })
    this.props.onChange(e)
  }

  render () {
    const { isChecked, isBasicStyle = false, id, className, disabled } = this.props
    const { isChanged } = this.state

    const gtmId = `${id}_${isChanged ? 'disabled' : 'enabled'}`
    return (
      <SwitchStyle isBasicStyle={isBasicStyle} className={className}>
        <label className={`switch  ${id}`} data-gtm-element-id={gtmId}>
          {
            (isChecked === true || isChecked === false)
              ? <input disabled={disabled} data-gtm-element-id={gtmId} checked={isChecked} type='checkbox' onChange={this.handleChange} />
              : <input disabled={disabled} data-gtm-element-id={gtmId} type='checkbox' onChange={this.handleChange} />
          }
          <span data-gtm-element-id={gtmId} className={`slider round ${id}`} />
        </label>
      </SwitchStyle>
    )
  }
}

export default Switch
