import { forwardRef, useCallback, useRef, useEffect, useState } from 'react'
import isEmpty from 'lodash/isEmpty'
import DynamicForm from '../../../../../../../components/DynamicForm'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'

function CustomerAddress(
  { customerAddress = {}, onChange, isAddressRequired = true },
  parentRef
) {
  const dataRef = useRef({})
  const [rerender, setRerender] = useState(1)
  const handleChange = useCallback(
    (data) => {
      dataRef.current = {
        ...dataRef.current,
        ...data,
      }
      onChange({
        ...dataRef.current,
      })
    },
    [onChange]
  )

  useEffect(() => {
    if (!isEmpty(customerAddress) && isEmpty(dataRef.current)) {
      dataRef.current = {
        customer_address: {
          ...customerAddress,
        },
      }
    }
  }, [customerAddress])

  useEffect(() => {
    // rerender when address is changes, action auto fill ocr
    setRerender((prev) => prev + 1)
  }, [customerAddress?.address])

  return (
    <>
      <CustomText
        color={AgentColorPallette.black}
        size="1em"
        top="1em"
        bottom="0.5em"
        weight={700}
      >
        Domisili Pelanggan (Tempat Tinggal)
      </CustomText>
      <DynamicForm
        key={rerender.toString()}
        form={[
          {
            type: 'address',
            name: 'customer_address',
            designV2: true,
            defaultValue: customerAddress,
            required: isAddressRequired,
          },
        ]}
        ref={parentRef}
        onChange={handleChange}
        isValidateOnChange
        isDocSlider
        formName="customerAddressForm"
      />
    </>
  )
}

export default forwardRef(CustomerAddress)
