import { regex } from '../../../../../../constants/regex'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../../lang/index'

export const getCustomerDocForm = (data = {}) => {
  return [
    {
      title: LANG_STRINGS.photoKTP,
      defaultValue: data?.ktp_url,
      name: 'ktp_url',
      type: 'uploadFileV3',
      required: true,
    },
    {
      type: 'inputNumberV2',
      title: LANG_STRINGS.ktpNumber,
      placeholder: 'Nomor KTP',
      error: ERROR_LANG.ktpError,
      defaultValue: data?.ktp_no,
      name: 'ktp_no',
      data: {
        subText: LANG_STRINGS.consist16Numbers,
      },
      required: true,
      regex_validation: regex.ktpNumber,
      errormsg: ERROR_LANG.ktpError,
    },
  ]
}

export const getCustomerNameForm = (data = {}) => {
  return [
    {
      type: 'inputV2',
      title: 'Nama Lengkap (sesuai KTP)',
      placeholder: 'Nama Lengkap (sesuai KTP)',
      regex_validation: regex.ktpName,
      errormsg: 'Nama tidak boleh ada digit',
      defaultValue: data?.name || data?.customer_name,
      name: 'name',
      required: true,
    },
    {
      type: 'inputNumberV2',
      title: LANG_STRINGS.customerPhone,
      placeholder: 'Nomor Handphone E.g., 08xxxxxxxxx',
      defaultValue: data?.mobile_no && data?.mobile_no.replace(/62-/g, '+62'),
      name: 'mobile_no',
      required: true,
      regex_validation: regex.phoneRegex,
      errormsg: ERROR_LANG.phoneNumberError,
    },
    {
      type: 'emailV2',
      title: LANG_STRINGS.emailAddress,
      placeholder: 'Alamat Email',
      defaultValue: data?.email,
      name: 'email',
      required: true,
      regex_validation: regex.emailRegex,
      errormsg: 'Format email tidak valid',
    },
  ]
}

export const FILE_TYPE_OCR = {
  KTP: 'ktp',
}
